WITH parsed AS (SELECT "Index", COALESCE(try_strptime("Date", '%Y-%m-%d %H:%M:%S'), try_strptime("Date", '%B %d, %Y at %I:%M %p'), try_strptime("Date", '%d %b %Y, %H:%M'))::DATE AS d, "High", "Low", "Close" FROM index_trade) SELECT "Index", COUNT(*) AS n_days, MIN(d) AS first_date, MAX(d) AS last_date, AVG(("High" - "Low") / "Close") AS avg_intraday_vol FROM parsed WHERE d >= DATE '2020-01-01' AND "Index" IN ('000001.SS','399001.SZ','HSI','N225','NSEI','TWII') GROUP BY "Index" ORDER BY avg_intraday_vol DESC;
